+// Sales from the till. Each sale line is one dish sold `qty` times; it keeps
+// the ingredient quantities it used, so later recipe changes do not rewrite
+// history. Tickets are imported once.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a sale with this ticket number was already imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities used by selling a dish `qty` times (one recipe portion each). */
+export function saleUses(store, dishId, qty) {
+  const dish = getDish(store, dishId);
+  return scaled(getRecipe(store, dish.recipeId), qty).filter((u) => u.qty > 0);
+}
+
+/**
+ * Records sale lines ({ row, ticket, soldAt, dishId, qty }) and consumes their
+ * ingredients with ref `sale:<ticket>`. All or nothing: stock is checked for
+ * every line first; a line that runs out throws bad_request naming its row.
+ */
+export function recordSales(store, lines) {
+  const planned = lines.map((l) => ({ ...l, uses: saleUses(store, l.dishId, l.qty) }));
+  const need = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const total = Math.round(((need.get(u.itemId) ?? 0) + u.qty) * 1000) / 1000;
+      const available = onHand(store, u.itemId);
+      if (total > available) {
+        const item = getItem(store, u.itemId);
+        const left = Math.max(0, Math.round((available - (need.get(u.itemId) ?? 0)) * 1000) / 1000);
+        throw new AppError("bad_request", { reason: `row ${p.row}: only ${left} ${item.unit} of ${item.name} left` });
+      }
+      need.set(u.itemId, total);
+    }
+  }
+  const before = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    const sales = [];
+    for (const p of planned) {
+      for (const u of p.uses) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+      const sale = { id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses };
+      store.data.sales.push(sale);
+      sales.push(sale);
+    }
+    return sales;
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement, and the
+ * difference (actual minus theoretical). Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.uses) theoretical.set(u.itemId, (theoretical.get(u.itemId) ?? 0) + u.qty);
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  const ids = [...new Set([...theoretical.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const t = r3(theoretical.get(itemId) ?? 0);
+      const a = r3(actual.get(itemId) ?? 0);
+      const item = store.data.items.find((i) => i.id === itemId);
+      return { itemId, name: item?.name ?? null, unit: item?.unit ?? null, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
